"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type KeyboardEvent, type ReactNode, useEffect, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One action in a radial menu. The label names the icon and shows beside it on hover or focus. */
export interface RadialMenuItem {
  id: string;
  label: string;
  icon: ReactNode;
  onSelect: () => void;
}

/** Props for a radial menu. */
export interface RadialMenuProps {
  /** Names the trigger and the menu, for example "Add". */
  label: string;
  /** Four to eight actions fit the ring. */
  items: RadialMenuItem[];
  /** Distance in rem from the trigger's centre to each action's centre. */
  radius?: number;
  className?: string;
}

// Damping 40 is 2 × √400: critically damped, so each action lands on the ring without overshoot.
const FAN: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const GATHER: Transition = { duration: 0.15, ease: [0.55, 0.085, 0.68, 0.53] };
const INSTANT: Transition = { duration: 0 };
// The actions leave the trigger one after another, clockwise from the top.
const STAGGER = 0.025;
// Right and down go clockwise, left and up go back.
const RING_STEPS = new Map([
  ["ArrowRight", 1],
  ["ArrowDown", 1],
  ["ArrowLeft", -1],
  ["ArrowUp", -1],
]);

/** Where an action sits on the ring, clockwise from the top, in rem. */
const ringPoint = (index: number, count: number, radius: number) => {
  const angle = (index / count) * Math.PI * 2 - Math.PI / 2;
  return { x: `${Math.cos(angle) * radius}rem`, y: `${Math.sin(angle) * radius}rem` };
};

/**
 * A round button that fans its actions out in a ring around itself. Arrow keys
 * move around the ring, Escape closes it and returns to the button, and a
 * choice closes it. With reduced motion the ring appears in place.
 */
export function RadialMenu({ label, items, radius = 5, className }: RadialMenuProps) {
  const [open, setOpen] = useState(false);
  const reduceMotion = useReducedMotion();
  const trigger = useRef<HTMLButtonElement>(null);
  const root = useRef<HTMLDivElement>(null);
  const actions = useRef<(HTMLButtonElement | null)[]>([]);
  const menuId = useId();

  // A press outside the menu closes it, the way any menu does.
  useEffect(() => {
    if (!open) return;
    const close = (event: PointerEvent) => {
      if (event.target instanceof Node && !root.current?.contains(event.target)) setOpen(false);
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [open]);

  // Focus moves to the first action when the menu opens.
  useEffect(() => {
    if (open) actions.current[0]?.focus();
  }, [open]);

  const closeToTrigger = () => {
    setOpen(false);
    trigger.current?.focus();
  };

  const onMenuKey = (event: KeyboardEvent<HTMLDivElement>) => {
    const current = actions.current.findIndex((action) => action === document.activeElement);
    const step = RING_STEPS.get(event.key);
    if (step !== undefined) {
      event.preventDefault();
      const next = (current + step + items.length) % items.length;
      actions.current[next]?.focus();
    } else if (event.key === "Home" || event.key === "End") {
      event.preventDefault();
      actions.current[event.key === "Home" ? 0 : items.length - 1]?.focus();
    } else if (event.key === "Escape") {
      event.preventDefault();
      closeToTrigger();
    } else if (event.key === "Tab") {
      setOpen(false);
    }
  };

  return (
    <div ref={root} className={cn("relative inline-grid place-items-center", className)}>
      <button
        ref={trigger}
        type="button"
        aria-label={label}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        onClick={() => setOpen((value) => !value)}
        className="relative z-10 grid size-14 cursor-pointer touch-manipulation place-items-center rounded-full bg-primary text-primary-foreground shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background active:scale-95 motion-safe:transition-transform"
      >
        <motion.svg
          viewBox="0 0 20 20"
          aria-hidden="true"
          className="size-5"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          initial={false}
          animate={{ rotate: open ? 45 : 0 }}
          transition={reduceMotion ? INSTANT : FAN}
        >
          <path d="M10 4v12M4 10h12" />
        </motion.svg>
      </button>

      <AnimatePresence>
        {open ? (
          <div key="menu" id={menuId} role="menu" aria-label={label} onKeyDown={onMenuKey} className="absolute inset-0">
            {items.map((item, index) => {
              const point = ringPoint(index, items.length, radius);
              return (
                <motion.button
                  key={item.id}
                  ref={(node) => {
                    actions.current[index] = node;
                  }}
                  type="button"
                  role="menuitem"
                  aria-label={item.label}
                  tabIndex={-1}
                  onClick={() => {
                    item.onSelect();
                    closeToTrigger();
                  }}
                  initial={reduceMotion ? { ...point, opacity: 0 } : { x: "0rem", y: "0rem", scale: 0.5, opacity: 0 }}
                  animate={{ ...point, scale: 1, opacity: 1 }}
                  exit={reduceMotion ? { opacity: 0, transition: INSTANT } : { x: "0rem", y: "0rem", scale: 0.5, opacity: 0, transition: GATHER }}
                  transition={reduceMotion ? INSTANT : { ...FAN, delay: index * STAGGER }}
                  className="group absolute inset-0 m-auto grid size-11 cursor-pointer touch-manipulation place-items-center rounded-full border border-border bg-card text-foreground shadow-sm outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition-colors"
                >
                  <span aria-hidden="true" className="grid size-5 place-items-center">
                    {item.icon}
                  </span>
                  <span
                    aria-hidden="true"
                    className="pointer-events-none invisible absolute bottom-full left-1/2 mb-1.5 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-xs font-medium text-background opacity-0 group-hover:visible group-hover:opacity-100 group-focus-visible:visible group-focus-visible:opacity-100 motion-safe:transition-opacity"
                  >
                    {item.label}
                  </span>
                </motion.button>
              );
            })}
          </div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
